    private TextView text(String value,int size,int color){TextView v=new TextView(activity);v.setText(value);v.setTextSize(TypedValue.COMPLEX_UNIT_PX,size);v.setTextColor(color);v.setTypeface(Ui.medium);v.setGravity(Gravity.CENTER_VERTICAL);v.setIncludeFontPadding(false);return v;}
    private void put(FrameLayout parent,View view,int x,int y,int w,int h){FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(w,h);p.leftMargin=x;p.topMargin=y;parent.addView(view,p);}
    private GradientDrawable round(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(radius);return d;}
    private TextView button(String value,int size){TextView v=text(value,size,WHITE);v.setId(View.generateViewId());v.setFocusable(true);v.setFocusableInTouchMode(true);v.setDefaultFocusHighlightEnabled(false);v.setSingleLine();v.setEllipsize(TextUtils.TruncateAt.END);v.setGravity(Gravity.CENTER);v.setPadding(16,0,16,0);v.setBackground(round(0xFF24262F,23));v.setOnFocusChangeListener((view,focus)->{v.setTextColor(focus?BG:WHITE);v.setBackground(round(focus?Appearance.accent(activity):v.isSelected()?Appearance.tint(activity,0x25):0xFF24262F,23));if(focus)host.contentFocused(v);});return v;}
    private void save(){if(source.isEmpty())return;SharedPreferences.Editor e=LiveTvData.prefs(activity).edit().putString("tv-group-"+LiveTvData.hash(source),group).putInt("tv-page-"+LiveTvData.hash(source),page);if(selected!=null)e.putString("last-"+LiveTvData.hash(source),selected.id).putString("last-family-"+LiveTvData.hash(source),TvChannelNames.family(selected));e.apply();}
    void resume(){if(closed)return;boolean wantedView=LiveTvData.guideView(activity);if(guideMode!=wantedView){guideMode=wantedView;applyView();}active=true;String identity=LiveTvData.source(activity);if(!source.equals(identity)){if(player!=null){player.pause();videoHost.removeView(player);player=null;}source=identity;total=0;mode=LiveTvData.mode(activity);group=LiveTvData.prefs(activity).getString("tv-group-"+LiveTvData.hash(source),"");page=LiveTvData.prefs(activity).getInt("tv-page-"+LiveTvData.hash(source),0);selected=null;}origin.setText((mode.equals("xtream")?"Xtream":mode.equals("antenna")?t("Antena","Antenna","Antena"):"M3U")+"  ⌄");if(player!=null)player.resume();else load(page,true);main.removeCallbacks(tick);tick.run();}
    void pause(){save();active=false;pickerEpoch++;if(pickerJob!=null)pickerJob.cancel(true);epoch++;guideEpoch++;timelineEpoch++;guideLoading=false;if(catalogJob!=null)catalogJob.cancel(true);if(guideJob!=null)guideJob.cancel(true);if(timelineJob!=null)timelineJob.cancel(true);main.removeCallbacks(tick);main.removeCallbacks(switchCategory);categoryPending=false;if(player!=null)player.pause();if(logos!=null){logos.close();logos=null;}heroLogo.setImageDrawable(null);detailLogo.setImageDrawable(null);detailLogoId="";for(ImageView i:logosOnScreen)i.setImageDrawable(null);}
    void destroy(){if(closed)return;pause();closed=true;if(player!=null){videoHost.removeView(player);player=null;}closeSheet();io.shutdownNow();main.removeCallbacksAndMessages(null);}
    private String groupName(List<TvCatalogCache.Group> values,String id){for(TvCatalogCache.Group g:values)if(g.id.equals(id))return g.name;return "";}
    private void load(int requested,boolean focus){
        if(!active||closed||requested<0||requested>0&&total>0&&(long)requested*12>=total)return;categoryPending=false;final int requestedSlot=preferredSlot;preferredSlot=-1;if(catalogJob!=null)catalogJob.cancel(true);if(guideJob!=null)guideJob.cancel(true);if(timelineJob!=null)timelineJob.cancel(true);loading=true;guideLoading=false;int token=++epoch;guideEpoch++;timelineEpoch++;String wantedMode=mode,wantedSource=source,wantedGroup=group,selectedId=selected==null?LiveTvData.prefs(activity).getString("last-"+LiveTvData.hash(source),""):selected.id;
        status.setText(t("Carregando canais…","Loading channels…","Cargando canales…"));catalogJob=io.submit(()->{try{
            List<TvCatalogCache.Group> options=new ArrayList<>();options.add(new TvCatalogCache.Group(ALL,t("Todos os canais","All channels","Todos los canales"),0));options.add(new TvCatalogCache.Group(FAVORITES,"★ "+t("Favoritos","Favorites","Favoritos"),0));TvCatalogCache.Page result;Set<String> saved;String chosen=wantedGroup;
            if(wantedMode.equals("xtream")){for(XtreamClient.Category g:xtream.categories(false))options.add(new TvCatalogCache.Group("@xc:"+g.id,g.name,0));saved=xtream.favoriteIds();if(chosen.isEmpty())chosen=options.size()>2?options.get(2).id:ALL;if(groupName(options,chosen).isEmpty())chosen=ALL;XtreamClient.Page p=chosen.equals(FAVORITES)?xtream.favoritePage(requested,""):xtream.page(chosen.equals(ALL)?"*":chosen.substring(4),groupName(options,chosen),requested,"",false);result=new TvCatalogCache.Page(p.channels,p.page,p.total);}
            else{saved=LiveTvData.favorites(activity,wantedSource);if(wantedMode.equals("m3u")){m3u.refresh(false);for(TvCatalogCache.Group g:m3u.groups())options.add(new TvCatalogCache.Group("@m3u:"+g.id,g.name,g.count));if(groupName(options,chosen).isEmpty())chosen=ALL;result=m3u.page(chosen.startsWith("@m3u:")?chosen.substring(5):null,"",chosen.equals(FAVORITES)?saved:null,requested);}else{if(groupName(options,chosen).isEmpty())chosen=ALL;result=antenna.page("",chosen.equals(FAVORITES)?saved:null,requested);}}
            String actualGroup=chosen;main.post(()->{if(!active||closed||token!=epoch||!wantedSource.equals(LiveTvData.source(activity)))return;loading=false;groups.clear();groups.addAll(options);channels=result.channels;total=result.total;page=result.page;group=actualGroup;favorites=saved;guide=Collections.emptyMap();selected=channels.isEmpty()?null:channels.get(0);for(LiveTvData.Channel ch:channels)if(ch.id.equals(selectedId))selected=ch;if(requestedSlot>=0&&!channels.isEmpty())selected=channels.get(Math.min(requestedSlot,channels.size()-1));syncCategories();render(focus);save();loadGuide();});
        }catch(Exception error){main.post(()->{if(!active||closed||token!=epoch)return;loading=false;status.setText(t("Não foi possível carregar. Confira a fonte em Ajustes → TV em direto.","Could not load channels. Check your source in Settings → Live TV.","No se han podido cargar los canales. Revisa la fuente en Ajustes → TV en directo."));watch.setEnabled(false);if(cards.isEmpty())origin.requestFocus();});}});
    }
    private void render(boolean focus){
        if(logos==null)logos=new LiveTvLogos(activity);logos.page();for(ImageView i:logosOnScreen)i.setImageDrawable(null);logosOnScreen.clear();cards.clear();programmeLabels.clear();times.clear();bars.clear();channelRow.removeAllViews();timeline.removeAllViews();timelineLogos.clear();heroLogo.setImageDrawable(null);detailLogo.setImageDrawable(null);detailLogoId="";detailProgramme=null;
        section.setText(group.equals(FAVORITES)?t("Seus favoritos","Your favorites","Tus favoritos"):displayGroup(groupName(groups,group)));emptyChannels.setVisibility(channels.isEmpty()?VISIBLE:GONE);emptyChannels.setText(t("Não há canais nesta categoria. Use ↑ ↓ para mudar de lista.","No channels in this category. Use ↑ ↓ to change lists.","No hay canales en esta categoría. Usa ↑ ↓ para cambiar de lista."));pages.setText(total==0?"0 / 0":(page+1)+" / "+((total+11)/12));previous.setEnabled(page>0);previous.setAlpha(page>0?1:.3f);next.setEnabled((page+1)*12<total);next.setAlpha(next.isEnabled()?1:.3f);watch.setEnabled(selected!=null);favorite.setEnabled(selected!=null);
        status.setText(channels.isEmpty()?t("Não há canais nesta seleção. Escolha outra categoria.","No channels in this selection. Choose another category.","No hay canales en esta selección. Elige otra categoría."):t("↑ ↓ Categoria   ·   OK Ver   ·   Manter OK Favorito","↑ ↓ Category   ·   OK Watch   ·   Hold OK Favorite","↑ ↓ Categoría   ·   OK Ver   ·   Mantener OK Favorito"));
        if(guideMode){updateHero();updateDetail();loadTimeline(focus);return;}
        for(int index=0;index<channels.size();index++){
            LiveTvData.Channel ch=channels.get(index);FrameLayout card=new FrameLayout(activity);card.setId(View.generateViewId());card.setFocusable(true);card.setClickable(true);card.setDefaultFocusHighlightEnabled(false);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(220,304);p.rightMargin=14;channelRow.addView(card,p);cards.add(card);
            TvLogoTile tile=new TvLogoTile(activity);put(card,tile,8,0,204,172);LiveTvLogos.LogoView logo=new LiveTvLogos.LogoView(activity,TvChannelNames.display(ch.name));logo.setColorListener(tile::color);logo.setScaleType(ImageView.ScaleType.FIT_CENTER);put(tile,logo,24,24,156,124);logosOnScreen.add(logo);logos.load(ch,logo);
            TextView name=text(TvChannelNames.display(ch.name),21,WHITE);name.setGravity(Gravity.CENTER);name.setSingleLine();name.setEllipsize(TextUtils.TruncateAt.END);put(card,name,0,184,220,30);
            TextView programme=text("",16,DIM);programme.setGravity(Gravity.CENTER);programme.setSingleLine();programme.setEllipsize(TextUtils.TruncateAt.END);put(card,programme,0,224,220,26);programmeLabels.add(programme);
            TextView remaining=text("",15,DIM);remaining.setGravity(Gravity.CENTER);remaining.setSingleLine();put(card,remaining,0,255,220,23);times.add(remaining);
            ProgressBar progress=new ProgressBar(activity,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(1000);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(Appearance.accent(activity)));progress.setProgressBackgroundTintList(android.content.res.ColorStateList.valueOf(0xFF363945));put(card,progress,18,290,184,3);bars.add(progress);
            int slot=index;card.setOnFocusChangeListener((v,has)->{tile.focused(has);if(has){host.contentFocused(v);select(ch);card.requestRectangleOnScreen(new Rect(-32,0,252,304),true);}});card.setOnClickListener(v->play(ch));card.setOnLongClickListener(v->{held=true;selected=ch;toggleFavorite();return true;});card.setNextFocusUpId(watch.getId());card.setOnKeyListener((v,key,event)->{if(event.getAction()!=KeyEvent.ACTION_DOWN)return false;if(key==KeyEvent.KEYCODE_DPAD_LEFT&&slot==0){focusCategories();consumeUp=key;return true;}if(key==KeyEvent.KEYCODE_DPAD_RIGHT&&slot==cards.size()-1&&(page+1)*12<total){load(page+1,true);return true;}return false;});
        }
        select(selected);if(guideMode)loadTimeline(focus);else if(focus){if(!cards.isEmpty())cards.get(Math.max(0,channels.indexOf(selected))).requestFocus();else emptyChannels.requestFocus();}
    }
    private void select(LiveTvData.Channel channel){selected=channel;updateHero();if(!guideMode&&logos!=null&&channel!=null)logos.load(channel,heroLogo);}
    private static String clock(long seconds){return Ui.time(seconds*1000);}
    private void updateHero(){
        if(selected==null){title.setText(t("Sua televisão, aqui.","Your TV, right here.","Tu televisión, aquí."));station.setText("");when.setText("");nextShow.setText("");return;}
        LiveTvData.Guide g=guide.get(selected.id);LiveTvData.Programme p=g==null?null:g.current(System.currentTimeMillis()/1000);title.setText(p==null?TvChannelNames.display(selected.name):p.title);station.setText(TvChannelNames.display(selected.name)+"  ·  "+(selected.group.isEmpty()?t("Em direto","Live TV","TV en directo"):selected.group));when.setText(p==null?t("Programação não disponível","Programme guide unavailable","Programación no disponible"):clock(p.start)+"–"+clock(p.end)+"   ·   "+LiveTvActivity.remainingText(p.remainingMinutes(System.currentTimeMillis()/1000)));nextShow.setText(g==null||g.next==null?"":t("A seguir · ","Up next · ","A continuación · ")+clock(g.next.start)+"  "+g.next.title);favorite.setText(TvChannelNames.favorite(selected,favorites)?"★":"☆");
    }
    private void updateProgrammes(){long now=System.currentTimeMillis()/1000;for(int i=0;i<channels.size()&&i<programmeLabels.size();i++){LiveTvData.Guide g=guide.get(channels.get(i).id);LiveTvData.Programme p=g==null?null:g.current(now);programmeLabels.get(i).setText(p==null?t("Em direto","Live","En directo"):p.title);times.get(i).setText(p==null?"":LiveTvActivity.remainingText(p.remainingMinutes(now)));bars.get(i).setVisibility(p==null?INVISIBLE:VISIBLE);bars.get(i).setProgress(p==null?0:p.progress(now));}updateHero();timeline.minute(now);if(guideMode)updateDetail();updatePlayerMetadata();}
    private void loadGuide(){
        if(!active||closed||channels.isEmpty()||guideLoading)return;guideLoading=true;if(guideJob!=null)guideJob.cancel(true);int token=++guideEpoch,generation=epoch;List<LiveTvData.Channel> snapshot=new ArrayList<>(channels);String current=mode;guideJob=io.submit(()->{Map<String,LiveTvData.Guide> result=new HashMap<>();try{try{result.putAll(new XmlTvGuide(activity).guide(snapshot));}catch(Exception unavailable){if(Thread.currentThread().isInterrupted())throw unavailable;}List<LiveTvData.Channel> missing=new ArrayList<>();long now=System.currentTimeMillis()/1000;for(LiveTvData.Channel ch:snapshot)if(!result.containsKey(ch.id)||result.get(ch.id).current(now)==null)missing.add(ch);if(!missing.isEmpty()){Map<String,LiveTvData.Guide> fallback=current.equals("xtream")?xtream.guide(missing):current.equals("antenna")?antenna.guide(missing):m3u.guide(missing);for(Map.Entry<String,LiveTvData.Guide> item:fallback.entrySet())if(!result.containsKey(item.getKey())||item.getValue().current(now)!=null)result.put(item.getKey(),item.getValue());}}catch(Exception unavailable){}main.post(()->{if(!active||closed||token!=guideEpoch||generation!=epoch)return;guideLoading=false;guide=result;guideAt=SystemClock.elapsedRealtime();updateProgrammes();if(guideMode&&player==null)loadTimeline(false);});});
    }
    private void applyView(){
        for(View column:new View[]{category,categoryViewport,categoryHelp})column.setVisibility(guideMode?VISIBLE:GONE);
        hero.setVisibility(guideMode?GONE:VISIBLE);channelPane.setVisibility(guideMode?GONE:VISIBLE);guidePane.setVisibility(guideMode?VISIBLE:GONE);
        for(View v:new View[]{previous,next,pages,status})v.setVisibility(guideMode?GONE:VISIBLE);
        guideOffset=Math.max(0,channels.indexOf(selected))/6*6;
    }
    private void updateDetail(){
        if(!guideMode)return;
        LiveTvData.Programme p=detailProgramme;long now=System.currentTimeMillis()/1000;
        String name=selected==null?"":TvChannelNames.display(selected.name);
        guideDetail.setText(p==null?t("Sem programação","No programme information","Sin programación"):p.title);
        guideStation.setText(name+(p==null?"":"  ·  "+clock(p.start)+"–"+clock(p.end)));
        guideTiming.setText(p==null?"":p.current(now)?t("Em direto  ·  ","Live now  ·  ","En emisión  ·  ")+LiveTvActivity.remainingText(p.remainingMinutes(now)):p.start>now?t("A seguir  ·  ","Upcoming  ·  ","Próximamente  ·  ")+clock(p.start):t("Terminado","Ended","Finalizado"));
        detailProgress.setVisibility(p==null?INVISIBLE:VISIBLE);detailProgress.setProgress(p==null?0:p.end<=now?1000:p.progress(now));
        String key=selected==null?"":selected.id+":"+selected.logo;
        if(!key.equals(detailLogoId)){detailLogoId=key;detailLogo.setImageDrawable(null);if(selected!=null&&logos!=null)logos.load(selected,detailLogo);}
    }
    private boolean guideMove(int direction){int offset=guideOffset+direction*6;if(offset>=0&&offset<channels.size()){guideOffset=offset;loadTimeline(true);return true;}int target=page+direction;if(target>=0&&target*12<total){guideOffset=direction>0?0:6;load(target,true);return true;}return false;}
    private void shift(int direction){long present=TvTimelineView.present(System.currentTimeMillis()/1000);guideStart=Math.max(present,Math.min(present+45*3600,guideStart+direction*5400));loadTimeline(true);}
    private void loadTimeline(boolean focus){
        if(!active||closed||!guideMode)return;if(timelineJob!=null)timelineJob.cancel(true);int timelineToken=++timelineEpoch;for(ImageView old:timelineLogos){old.setImageDrawable(null);logosOnScreen.remove(old);}timelineLogos.clear();detailLogoId="";detailLogo.setImageDrawable(null);detailProgramme=null;guideOffset=Math.min(guideOffset,Math.max(0,(channels.size()-1)/6*6));guideChannels=new ArrayList<>(channels.subList(guideOffset,Math.min(channels.size(),guideOffset+6)));timeline.removeAllViews();if(logos==null)logos=new LiveTvLogos(activity);logos.page();for(int i=0;i<guideChannels.size();i++){LiveTvLogos.LogoView logo=new LiveTvLogos.LogoView(activity,TvChannelNames.display(guideChannels.get(i).name));logo.setScaleType(ImageView.ScaleType.FIT_CENTER);put(timeline,logo,10,timeline.logoY(i),60,60);logosOnScreen.add(logo);timelineLogos.add(logo);logos.load(guideChannels.get(i),logo);}timeline.data(guideChannels,Collections.emptyMap(),guideStart,selected,true);updateDetail();if(focus)timeline.requestFocus();int generation=epoch;long from=guideStart;List<LiveTvData.Channel> snapshot=new ArrayList<>(guideChannels);Map<String,LiveTvData.Guide> fallback=new HashMap<>(guide);
        timelineJob=io.submit(()->{Map<String,List<LiveTvData.Programme>> result=new HashMap<>();try{result.putAll(new XmlTvGuide(activity).window(snapshot,from));if(mode.equals("antenna"))result.putAll(antenna.window(snapshot,from));}catch(Exception unavailable){}for(LiveTvData.Channel ch:snapshot){List<LiveTvData.Programme> programmes=new ArrayList<>(result.getOrDefault(ch.id,Collections.emptyList()));LiveTvData.Guide g=fallback.get(ch.id);if(g!=null)for(LiveTvData.Programme p:new LiveTvData.Programme[]{g.now,g.next})if(p!=null&&p.end>from&&p.start<from+TvTimelineView.SECONDS){boolean overlap=false;for(LiveTvData.Programme known:programmes)if(known.start<p.end&&known.end>p.start)overlap=true;if(!overlap)programmes.add(p);}programmes.sort((a,b)->Long.compare(a.start,b.start));result.put(ch.id,new ArrayList<>(programmes.subList(0,Math.min(TvTimelineView.MAX_PROGRAMMES,programmes.size()))));}main.post(()->{if(!active||closed||!guideMode||generation!=epoch||timelineToken!=timelineEpoch||from!=guideStart)return;timeline.data(snapshot,result,from,selected,false);});});
    }
    private void toggleFavorite(){if(selected==null)return;if(!TvChannelNames.favorite(selected,favorites)&&favorites.size()>=128){status.setText(t("Máximo 128 favoritos.","Maximum 128 favorites.","Máximo 128 favoritos."));return;}try{if(mode.equals("xtream")){xtream.toggleFavorite(selected);favorites=xtream.favoriteIds();}else{if(TvChannelNames.favorite(selected,favorites)){for(LiveTvData.Channel ch:TvChannelNames.variants(selected))if(favorites.contains(ch.id))LiveTvData.toggle(activity,source,ch.id);}else LiveTvData.toggle(activity,source,selected.id);favorites=LiveTvData.favorites(activity,source);}updateHero();updatePlayerMetadata();}catch(Exception unavailable){status.setText(t("Não foi possível guardar o favorito.","Could not save favorite.","No se ha podido guardar el favorito."));}}
    private void play(LiveTvData.Channel ch){if(ch==null||loading||!source.equals(LiveTvData.source(activity))||!ch.playable())return;selected=ch;save();closeSheet();if(player==null){if(logos!=null){logos.close();logos=null;}heroLogo.setImageDrawable(null);detailLogo.setImageDrawable(null);detailLogoId="";for(ImageView image:logosOnScreen)image.setImageDrawable(null);player=new LiveTvPlayer(activity,new LiveTvPlayer.Actions(){public void back(){browse();}public void zap(int direction){int index=channels.indexOf(selected)+direction;if(index>=0&&index<channels.size())play(channels.get(index));}public void channels(int page){loadPlayerChannels(page);}public void choose(LiveTvData.Channel channel){choosePlayerChannel(channel);}});videoHost.addView(player,new FrameLayout.LayoutParams(-1,-1));}pickerEpoch++;if(pickerJob!=null)pickerJob.cancel(true);player.channels(channels,guide,displayGroup(groupName(groups,group)),page,total);player.select(ch);updatePlayerMetadata();player.resume();}
    private void updatePlayerMetadata(){if(player==null||selected==null)return;LiveTvData.Guide g=guide.get(selected.id);player.metadata(g==null?null:g.current(System.currentTimeMillis()/1000),g==null?null:g.next);}
    private void choosePlayerChannel(LiveTvData.Channel channel){if(player==null)return;epoch++;guideEpoch++;timelineEpoch++;if(catalogJob!=null)catalogJob.cancel(true);if(guideJob!=null)guideJob.cancel(true);if(timelineJob!=null)timelineJob.cancel(true);loading=false;guideLoading=false;channels=new ArrayList<>(player.pickerChannels);guide=new HashMap<>(player.pickerGuide);page=player.pickerPage;total=player.pickerTotal;guideOffset=Math.max(0,channels.indexOf(channel))/6*6;play(channel);loadGuide();}
    private void loadPlayerChannels(int requested){
        if(!active||closed||player==null)return;if(pickerJob!=null)pickerJob.cancel(true);int token=++pickerEpoch;LiveTvPlayer target=player;String wantedSource=source,wantedMode=mode,wantedGroup=group,label=displayGroup(groupName(groups,group));
        pickerJob=io.submit(()->{try{TvCatalogCache.Page result=TvPlayerCatalog.page(activity,wantedMode,wantedGroup,label,"",requested);main.post(()->{if(active&&!closed&&token==pickerEpoch&&player==target&&wantedSource.equals(LiveTvData.source(activity)))target.channels(result.channels,Collections.emptyMap(),label,result.page,result.total);});Map<String,LiveTvData.Guide> programmes=TvPlayerCatalog.guide(activity,wantedMode,result.channels);main.post(()->{if(active&&!closed&&token==pickerEpoch&&player==target&&wantedSource.equals(LiveTvData.source(activity)))target.channelGuide(programmes);});}catch(Exception unavailable){main.post(()->{if(active&&!closed&&token==pickerEpoch&&player==target)target.channelError();});}});
    }
    private void browse(){pickerEpoch++;if(pickerJob!=null)pickerJob.cancel(true);if(player!=null){player.pause();videoHost.removeView(player);player=null;}render(true);save();loadGuide();}
    private void openSheet(String name){host.modal(true);sheet.removeAllViews();sheet.setVisibility(VISIBLE);TextView heading=text(name,40,WHITE);put(sheet,heading,82,54,1500,78);}
    private void closeSheet(){if(sheet.getVisibility()==VISIBLE){sheet.setVisibility(GONE);sheet.removeAllViews();host.modal(false);}}
    private void action(String name,int y,Runnable run){TextView b=button(name,24);put(sheet,b,82,y,980,70);b.setOnClickListener(v->{closeSheet();run.run();});if(y==174)b.requestFocus();}
    private String displayGroup(String value){return value.replaceFirst("(?i)^ES\\s*[|:]\\s*","");}
    private int categoryIndex(){for(int i=0;i<groups.size();i++)if(groups.get(i).id.equals(group))return i;return 0;}
    private void syncCategories(){categoryAdapter.notifyDataSetChanged();int index=categoryIndex();categoryList.setItemChecked(index,true);if(index<categoryList.getFirstVisiblePosition()||index>categoryList.getLastVisiblePosition())categoryList.setSelection(index);}
    private void focusCategories(){if(!guideMode){host.focusNavigation();return;}categoryList.requestFocus();categoryList.setSelection(categoryIndex());}
    private void chooseCategory(int index,boolean preserveColumn){
        if(index<0||index>=groups.size())return;if(groups.get(index).id.equals(group)&&!loading){focusContent();return;}
        preferredSlot=preserveColumn?Math.max(0,channels.indexOf(selected)):0;group=groups.get(index).id;page=0;guideOffset=0;loading=true;categoryPending=true;epoch++;guideEpoch++;timelineEpoch++;
        if(catalogJob!=null)catalogJob.cancel(true);if(guideJob!=null)guideJob.cancel(true);if(timelineJob!=null)timelineJob.cancel(true);syncCategories();status.setText(t("Carregando ","Loading ","Cargando ")+displayGroup(groupName(groups,group))+"…");
        main.removeCallbacks(switchCategory);main.postDelayed(switchCategory,120);
    }
    private void sourcePicker(){openSheet(t("Sua televisão","Your television","Tu televisión"));int y=174;for(String choice:new String[]{"m3u","xtream","antenna"}){action(choice.equals("m3u")?"M3U":choice.equals("xtream")?"Xtream":t("Antena","Antenna","Antena"),y,()->{if(choice.equals("xtream")&&!xtream.connected()){activity.startActivity(new Intent(activity,XtreamLinkActivity.class));return;}save();LiveTvData.select(activity,choice);source="";resume();});y+=94;}}
    private void upcoming(LiveTvData.Channel ch,LiveTvData.Programme p){openSheet(p.title);TextView hint=text(TvChannelNames.display(ch.name)+" · "+clock(p.start)+"–"+clock(p.end)+" · "+(p.end<=System.currentTimeMillis()/1000?t("Terminado","Ended","Finalizado"):t("A seguir","Upcoming","Próximamente")),24,DIM);put(sheet,hint,82,140,1500,70);action(t("Ver canal em direto","Watch channel live","Ver canal en directo"),270,()->play(ch));View action=sheet.getChildAt(sheet.getChildCount()-1);action.requestFocus();}
    boolean onKey(KeyEvent event){int key=event.getKeyCode();if(event.getAction()==KeyEvent.ACTION_UP&&key==consumeUp){consumeUp=-1;return true;}if(held&&(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER)){if(event.getAction()==KeyEvent.ACTION_UP)held=false;return true;}if(player!=null){boolean handled=player.key(event);if(handled&&event.getAction()==KeyEvent.ACTION_DOWN)consumeUp=key;return handled;}if(sheet.getVisibility()==VISIBLE){if(key==KeyEvent.KEYCODE_BACK){if(event.getAction()==KeyEvent.ACTION_UP){closeSheet();if(guideMode)timeline.requestFocus();else emptyChannels.requestFocus();}return true;}return false;}View focused=activity.getCurrentFocus();if(!guideMode&&event.getAction()==KeyEvent.ACTION_DOWN&&(cards.contains(focused)||focused==emptyChannels)&&(key==KeyEvent.KEYCODE_DPAD_DOWN||key==KeyEvent.KEYCODE_DPAD_UP)){int direction=key==KeyEvent.KEYCODE_DPAD_DOWN?1:-1;int target=categoryIndex()+direction;if(target>=0&&target<groups.size())chooseCategory(target,true);else if(direction<0)watch.requestFocus();consumeUp=key;return true;}if(key==KeyEvent.KEYCODE_DPAD_LEFT&&event.getAction()==KeyEvent.ACTION_DOWN&&(activity.getCurrentFocus()==watch||activity.getCurrentFocus()==origin||activity.getCurrentFocus()==categoryList)){host.focusNavigation();return true;}return false;}
    void focusContent(){if(guideMode)timeline.requestFocus();else if(!cards.isEmpty())cards.get(Math.max(0,channels.indexOf(selected))).requestFocus();else emptyChannels.requestFocus();}
